use std::sync::Arc;
use axum::{extract::Query,response::{IntoResponse,Response},Json};
use serde_json::{json,Value};
use sqlx::{postgres::PgRow,Row};
use uuid::Uuid;
use crate::{security::require_proxy_context,state::AppState};
use super::{queries,responses::{api_error,unavailable},types::*};

async fn signed(h:&axum::http::HeaderMap,s:&AppState)->Result<queries::ApiPrincipal,Response>{
 require_proxy_context(h,s)?;let val=|name:&str|h.get(name).and_then(|v|v.to_str().ok());
 let (Some(member),Some(key),Some(sig))=(val("x-open-api-member_id"),val("x-open-api-api_key"),val("x-open-api-signature"))else{return Err(api_error(axum::http::StatusCode::UNAUTHORIZED,"Invalid API key"))};
 queries::authenticate(&s.pg_pool,member,key,sig,val("x-open-api-ref_id")).await.map_err(|_|unavailable())?.ok_or_else(||api_error(axum::http::StatusCode::UNAUTHORIZED,"Invalid API key"))
}
pub async fn profile(h:axum::http::HeaderMap,axum::extract::State(s):axum::extract::State<Arc<AppState>>)->Response{let p=match signed(&h,&s).await{Ok(v)=>v,Err(r)=>return r};match sqlx::query("SELECT name FROM users WHERE id=$1").bind(p.id).fetch_optional(&s.pg_pool).await{Ok(Some(r))=>Json(ApiProfileResponse{success:true,data:ApiProfileData{name:r.get("name"),email:p.email,level:p.level,balance:p.balance}}).into_response(),Ok(None)=>api_error(axum::http::StatusCode::NOT_FOUND,"User not found"),Err(_)=>unavailable()}}
pub async fn categories(h:axum::http::HeaderMap,axum::extract::State(s):axum::extract::State<Arc<AppState>>)->Response{if let Err(r)=signed(&h,&s).await{return r};match sqlx::query("SELECT id,name,slug FROM categories WHERE status ORDER BY sort_order,name").fetch_all(&s.pg_pool).await{Ok(rows)=>Json(ApiDataResponse{success:true,data:rows.iter().map(|r|ApiCategoryItem{id:r.get::<Uuid,_>("id").to_string(),name:r.get("name"),slug:r.get("slug")}).collect::<Vec<_>>()} ).into_response(),Err(_)=>unavailable()}}
pub async fn operators(h: axum::http::HeaderMap, axum::extract::State(state): axum::extract::State<Arc<AppState>>, Query(query): Query<ApiOperatorsQuery>) -> Response {
    if let Err(response) = signed(&h, &state).await { return response; }
    match sqlx::query("SELECT o.id,o.name,o.slug,c.name AS category FROM operators o JOIN categories c ON c.id=o.category_id WHERE o.status AND ($1::text IS NULL OR c.id::text=$1 OR c.slug=$1) ORDER BY o.sort_order,o.name")
        .bind(query.category).fetch_all(&state.pg_pool).await {
        Ok(rows) => Json(ApiDataResponse { success: true, data: rows.iter().map(|row| ApiOperatorItem {
            id: row.get::<Uuid, _>("id").to_string(), name: row.get("name"), slug: row.get("slug"), category: row.get("category"),
        }).collect::<Vec<_>>() }).into_response(),
        Err(_) => unavailable(),
    }
}
pub async fn product_types(h:axum::http::HeaderMap,axum::extract::State(s):axum::extract::State<Arc<AppState>>,Query(q):Query<ApiProductTypesQuery>)->Response{if let Err(r)=signed(&h,&s).await{return r};match sqlx::query("SELECT t.id,t.name,t.slug,c.name category,o.name operator FROM product_types t JOIN categories c ON c.id=t.category_id JOIN operators o ON o.id=t.operator_id WHERE t.status AND ($1::text IS NULL OR c.id::text=$1 OR c.slug=$1) AND ($2::text IS NULL OR o.id::text=$2 OR o.slug=$2) ORDER BY t.sort_order,t.name").bind(q.category).bind(q.operator).fetch_all(&s.pg_pool).await{Ok(rows)=>Json(ApiDataResponse{success:true,data:rows.iter().map(|r|ApiProductTypeItem{id:r.get::<Uuid,_>("id").to_string(),name:r.get("name"),slug:r.get("slug"),category:r.get("category"),operator:r.get("operator")}).collect::<Vec<_>>()} ).into_response(),Err(_)=>unavailable()}}
pub async fn products(h:axum::http::HeaderMap,axum::extract::State(s):axum::extract::State<Arc<AppState>>,Query(q):Query<ApiProductsQuery>)->Response{let p=match signed(&h,&s).await{Ok(v)=>v,Err(r)=>return r};match sqlx::query("SELECT p.code,p.name,p.category,COALESCE(o.name,'') operator,COALESCE(t.name,'') type,p.price_basic,p.price_gold,p.price_platinum FROM products p LEFT JOIN operators o ON o.id=p.operator_id LEFT JOIN product_types t ON t.id=p.product_type_id WHERE p.status AND ($1::text IS NULL OR p.category_id::text=$1 OR p.category=$1) AND ($2::text IS NULL OR p.operator_id::text=$2 OR o.slug=$2) AND ($3::text IS NULL OR p.product_type_id::text=$3 OR t.slug=$3) ORDER BY p.sort_order,p.name").bind(q.category).bind(q.operator).bind(q.product_type).fetch_all(&s.pg_pool).await{Ok(rows)=>Json(ApiDataResponse{success:true,data:rows.iter().map(|r|{let price=match p.level.as_str(){"gold"=>r.get("price_gold"),"platinum"=>r.get("price_platinum"),_=>r.get("price_basic")};let code:String=r.get("code");let name:String=r.get("name");let category:String=r.get("category");let operator:String=r.get("operator");let ty:String=r.get("type");ApiProductItem{code:code.clone(),name:name.clone(),category:category.clone(),operator:operator.clone(),product_type:ty.clone(),product_code_alias:code,product_name_alias:name,category_name:category,operator_name:operator,jenis_name:ty,price,status:"available"}}).collect::<Vec<_>>()} ).into_response(),Err(_)=>unavailable()}}
pub async fn transactions(h:axum::http::HeaderMap,axum::extract::State(s):axum::extract::State<Arc<AppState>>,Query(q):Query<ApiTransactionsQuery>)->Response{let p=match signed(&h,&s).await{Ok(v)=>v,Err(r)=>return r};let page=q.page.unwrap_or(1).max(1);let limit=q.limit.unwrap_or(20).clamp(1,100);let total=match sqlx::query_scalar::<_,i64>("SELECT count(*) FROM financial_transactions WHERE user_id=$1 AND ($2::text IS NULL OR status=$2)").bind(p.id).bind(&q.status).fetch_one(&s.pg_pool).await{Ok(v)=>v,Err(_)=>return unavailable()};match sqlx::query("SELECT t.id,t.partner_ref,t.amount,t.status,t.snapshot,t.created_at,p.code,p.name FROM financial_transactions t JOIN products p ON p.id=t.product_id WHERE t.user_id=$1 AND ($2::text IS NULL OR t.status=$2) ORDER BY t.created_at DESC LIMIT $3 OFFSET $4").bind(p.id).bind(&q.status).bind(limit).bind((page-1)*limit).fetch_all(&s.pg_pool).await{Ok(rows)=>Json(ApiTransactionsResponse{success:true,data:rows.iter().map(transaction_item).collect(),pagination:ApiTransactionsPagination{page,limit,total,total_pages:total / limit + i64::from(total % limit != 0)}}).into_response(),Err(_)=>unavailable()}}
pub async fn transaction_check(h:axum::http::HeaderMap,axum::extract::State(s):axum::extract::State<Arc<AppState>>,Query(q):Query<ApiCheckTransactionQuery>)->Response{let p=match signed(&h,&s).await{Ok(v)=>v,Err(r)=>return r};if q.trx_id.as_deref().unwrap_or_default().trim().is_empty()&&q.ref_id.as_deref().unwrap_or_default().trim().is_empty(){return api_error(axum::http::StatusCode::BAD_REQUEST,"trx_id or ref_id is required")};let id=q.trx_id.and_then(|v|Uuid::parse_str(&v).ok());let row=sqlx::query("SELECT t.id,t.partner_ref,t.amount,t.status,t.snapshot,t.created_at,t.updated_at,p.code,p.name FROM financial_transactions t JOIN products p ON p.id=t.product_id WHERE t.user_id=$1 AND (($2::uuid IS NOT NULL AND t.id=$2) OR ($2::uuid IS NULL AND $3::text IS NOT NULL AND t.partner_ref=$3))").bind(p.id).bind(id).bind(q.ref_id).fetch_optional(&s.pg_pool).await;match row{Ok(Some(r))=>Json(ApiDataResponse{success:true,data:transaction_detail(&r)}).into_response(),Ok(None)=>api_error(axum::http::StatusCode::NOT_FOUND,"Transaction not found"),Err(_)=>unavailable()}}
fn transaction_item(r:&PgRow)->ApiTransactionItem{ApiTransactionItem{trx_id:json!(r.get::<Uuid,_>("id").to_string()),ref_id:r.get("partner_ref"),product_code:Some(r.get("code")),product_name:Some(r.get("name")),target:r.get::<Value,_>("snapshot").get("target").and_then(Value::as_str).unwrap_or("").to_owned(),price:r.get("amount"),status:r.get("status"),sn:None,created_at:r.get::<chrono::DateTime<chrono::Utc>,_>("created_at").to_rfc3339()}}
fn transaction_detail(r:&PgRow)->ApiTransactionDetail{let x=transaction_item(r);ApiTransactionDetail{trx_id:x.trx_id,ref_id:x.ref_id,product_code:x.product_code,product_name:x.product_name,target:x.target,price:x.price,status:x.status,sn:x.sn,created_at:x.created_at,updated_at:r.get::<chrono::DateTime<chrono::Utc>,_>("updated_at").to_rfc3339()}}
